 "content": "from collections import deque


def transform(grid):
    """Tile each embedded colored motif across its surrounding zero field."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 8 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                rr, cc = q.popleft()
                cells.append((rr, cc))
                for nr, nc in ((rr-1, cc), (rr+1, cc), (rr, cc-1), (rr, cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != 8 and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        q.append((nr, nc))

            colored = [(rr, cc) for rr, cc in cells if grid[rr][cc] != 0]
            if not colored:
                continue
            r0 = min(rr for rr, _ in colored)
            r1 = max(rr for rr, _ in colored)
            c0 = min(cc for _, cc in colored)
            c1 = max(cc for _, cc in colored)
            ph, pw = r1 - r0 + 1, c1 - c0 + 1
            motif = [grid[rr][c0:c0+pw] for rr in range(r0, r0+ph)]

            for rr, cc in cells:
                out[rr][cc] = motif[(rr-r0) % ph][(cc-c0) % pw]

    return out
